export enum GossipAction {
  IGNORE = "IGNORE",
  REJECT = "REJECT",
}

export enum GossipErrorCode {
  INVALID_SERIALIZED_BYTES_ERROR_CODE = "GOSSIP_ERROR_INVALID_SERIALIZED_BYTES",
